[{"i":0,"name":"未标定区域","salesTax":0,"pollTax":0,"treasury":0,"neighbors":[21],"diplomacy":[["Hakynthia-Methinian War","Hakynthia declared a war on its rival Methinoi","Methinoi's ally Chalidia joined the war on defenders side","Hakynthia's ally Hyeniontia avoided entering the war"],["Rila-Sanhasian War","Rila declared a war on its rival Sanhas"],["Andidilia-Vesosctian War","Andidilia declared a war on its rival Vesosctia","Vesosctia's vassal Plaven joined the war on defenders side","Vesosctia's ally Skonker joined the war on defenders side","Vesosctia's ally Tazanyania joined the war on defenders side"],["Minostab-Aloranarian War","Minostab declared a war on its rival Aloranar","Being already at war, Chalidia severed the defense pact with Aloranar","Minostab's ally Chalidia joined the war on attackers side"],["Porve-Alverian War","Porve declared a war on its rival Alver","Porve's vassal Soviles joined the war on attackers side","Being already at war, Skonker severed the defense pact with Alver","Alver's ally Lekhia joined the war on defenders side","Alver's ally Pyrnapia joined the war on defenders side","Alver's ally Gofogaria joined the war on defenders side","Porve's ally Hyeniontia avoided entering the war","Porve's ally Hvolsia avoided entering the war"]],"urban":0,"rural":0,"burgs":0,"area":321,"cells":6,"provinces":[],"note":""}]
